# ─── Added: missing top-level names from upstream matplotlib ────────


class ExecutableNotFoundError(FileNotFoundError):
    """Raised by :func:`_get_executable_info` when matplotlib can't find
    an external tool (ghostscript, ffmpeg, dvipng, …). The shim doesn't
    invoke these tools, so this class is exposed purely for isinstance
    checks in user code."""
    pass


# RcParams is the public name upstream uses; ``_RcParams`` is what we
# already define internally. Alias them so ``isinstance(rcParams,
# RcParams)`` matches.
RcParams = _RcParams


def get_data_path():
    """Path to matplotlib's data directory — used for sample data and
    fonts. The shim doesn't ship them, so we return the package dir."""
    import os
    return os.path.dirname(__file__)


def get_cachedir():
    """User cache directory for matplotlib (font cache, etc.)."""
    import os
    base = os.environ.get('MPLCONFIGDIR') or os.path.join(
        os.path.expanduser('~'), '.cache', 'matplotlib')
    os.makedirs(base, exist_ok=True)
    return base


def get_configdir():
    """User configuration directory for matplotlib."""
    import os
    base = os.environ.get('MPLCONFIGDIR') or os.path.join(
        os.path.expanduser('~'), '.config', 'matplotlib')
    os.makedirs(base, exist_ok=True)
    return base


def matplotlib_fname():
    """Path to the active matplotlibrc file. The shim has no rc file, so
    we return a sentinel string that callers can fall back from."""
    import os
    return os.path.join(get_configdir(), 'matplotlibrc')


_interactive_state = False


def interactive(b):
    """Toggle interactive mode. The plotly backend ignores this since
    every figure is rendered on ``show()``, but we honour the flag."""
    global _interactive_state
    _interactive_state = bool(b)


def is_interactive():
    """Return whether interactive mode is on."""
    return _interactive_state


# ─── Added: rcParam helpers from upstream matplotlib ────────────────


# Snapshot of the original rcParams — upstream uses this for rcdefaults().
rcParamsOrig = _RcParams()


def rc_params(fail_on_error=False):
    """Return a fresh :class:`RcParams` populated with the built-in
    defaults. The shim has a single static default set."""
    return _RcParams()


def rc_params_from_file(fname, fail_on_error=False, use_default_template=True):
    """Read a matplotlibrc file and return its rcParams. The shim
    doesn't actually parse one — returns a fresh defaults dict."""
    return _RcParams()


def rc_file(fname, *, use_default_template=True):
    """Apply rcParams from a matplotlibrc file to the global rcParams.
    No-op in the shim — we always use the plotly backend defaults."""
    return None


def rc_file_defaults():
    """Reset rcParams to whatever was loaded from the rc file at
    matplotlib import time (equivalent to a no-op rcdefaults() here)."""
    rcParams.clear()
    rcParams.update(rcParamsOrig)


# ─── Added: stub methods to match upstream class surface ────────
def _attach_remaining_stubs():
    def _stub(self, *a, **kw): return None
    if not hasattr(RcParams, 'find_all'): RcParams.find_all = _stub
    def _stub(self, *a, **kw): return None
    if not hasattr(RcParams, 'validate'): RcParams.validate = _stub
_attach_remaining_stubs()
